def analyze_input_influence(state_mean_std, policy_params_dict, input_data=None, output_target=None, mask=[1, 1, 1, 1], output_adjust=False):
    """分析输入特征影响力
    Args:
        policy_params_dict: 包含'params'键的字典，其下有hidden_0/hidden_1/hidden_2子字典
    """
    class PolicyNetwork(nn.Module):
        def __init__(self):
            super().__init__()
            self.fc1 = nn.Linear(120, 64)  # hidden_0
            self.fc2 = nn.Linear(64, 64)   # hidden_1
            self.fc3 = nn.Linear(64, 4)    # hidden_2
            self.silu = nn.SiLU()
            self.tanh = nn.Tanh()
        
        def forward(self, x):
            x = self.silu(self.fc1(x))
            # print("fc1 output:", ", ".join(f"{val:.6f}" for val in x.tolist())) # esp32: layer_output:1.526610,-0.248041,-0.261439,-0.029571,0.971680,-0.265239,-0.082698,-0.129752,-0.107403,4.474482,0.737618,0.104991,3.162908,2.151829,-0.221941,2.961222,1.220683,0.551516,-0.145128,1.888193,-0.271867,-0.018458,1.235431,-0.024466,-0.190223,1.695423,-0.141978,-0.186638,-0.026549,2.060238,3.320694,-0.272873,0.517025,-0.209755,-0.044866,-0.244271,-0.103600,6.146816,-0.195731,-0.129673,-0.041855,-0.254014,2.230974,2.698370,-0.110878,-0.269174,-0.102086,-0.032190,1.006267,-0.143999,1.226132,-0.234896,-0.155231,-0.102787,2.214954,0.668547,2.464192,-0.207880,-0.054985,-0.190192,4.219047,0.713075,-0.278376,-0.128722
            x = self.silu(self.fc2(x))
            # print("fc2 output:", ", ".join(f"{val:.6f}" for val in x.tolist()))
            x = self.fc3(x)
            return self.tanh(x) 
    
    model = PolicyNetwork()
    params = policy_params_dict['params']  # 获取params层级
    
    with torch.no_grad():
        # 加载第一层参数 (105→64) - kernel需要转置
        model.fc1.weight.copy_(torch.tensor(params['hidden_0']['kernel']).T)  # 添加.T转置
        model.fc1.bias.copy_(torch.tensor(params['hidden_0']['bias']))
        
        # 加载第二层参数 (64→64) - kernel需要转置
        model.fc2.weight.copy_(torch.tensor(params['hidden_1']['kernel']).T)  # 添加.T转置
        model.fc2.bias.copy_(torch.tensor(params['hidden_1']['bias']))
        
        # 加载第三层参数 (64→4) - kernel需要转置
        model.fc3.weight.copy_(torch.tensor(params['hidden_2']['kernel']).T[:4])  # 添加.T转置
        model.fc3.bias.copy_(torch.tensor(params['hidden_2']['bias'][:4]))
    
    # 计算输入梯度（影响力）
    if input_data is None:
        input_data = torch.randn(1, 120, requires_grad=True)
    else:
        if state_mean_std is not None:
            state_mean, state_std = state_mean_std
            input_data = (input_data - state_mean) / state_std
        # print("input_data normalized:", input_data)
        input_data = torch.tensor(input_data, dtype=torch.float32, requires_grad=True)
    if output_target is None:
        output_target = torch.zeros(1, 4)
    else:
        output_target = torch.tensor(output_target, dtype=torch.float32)
    output = model(input_data)
    # output = (output + torch.tensor([-1, -1, 0.0, 0.0])) * torch.tensor([0.25, 0.25, 1.5, 1.5])
    # output = (output + torch.tensor([0, 0, 0.0, 0.0])) * torch.tensor([0.25, 0.25, 1.5, 1.5])
    if output_adjust:
        output = (output + torch.tensor([0, 0, 0.0, 0.0])) * torch.tensor([0.25, 0.25, 0.06, 0.06])
    print("nn output:", output)
    mask = torch.tensor(mask)
    loss = torch.norm((output - output_target)*mask, p=2)
    loss.backward()
    gradients = input_data.grad.squeeze().numpy()
    
    return gradients


def load(
    path: Union[str, epath.Path],
):
  """Loads checkpoint."""
  path = epath.Path(path)
  if not path.exists():
    raise ValueError(f'checkpoint path does not exist: {path.as_posix()}')

  logging.info('restoring from checkpoint %s', path.as_posix())

  metadata = ocp.PyTreeCheckpointer().metadata(path)
  restore_args = jax.tree.map(
      lambda _: ocp.RestoreArgs(restore_type=np.ndarray), metadata
  )
  orbax_checkpointer = ocp.PyTreeCheckpointer()
  target = orbax_checkpointer.restore(
      path, ocp.args.PyTreeRestore(restore_args=restore_args), item=None
  )
  target[0] = running_statistics.RunningStatisticsState(**target[0])

  return target


def test():
    ckpt_path = os.environ['LEGWHEEL_CKPT_PATH']
    print(f"extract parameters from {ckpt_path}")
    target = load(ckpt_path)
    stats, policy_params, critic_params = target


    # 转换为float32 numpy数组
    state_mean = np.array(stats.mean['state'], dtype=np.float32)
    state_std = np.array(stats.std['state'], dtype=np.float32)
    
    # 保存到C++头文件，按列格式整理
    with open('params.cpp.txt', 'w') as f:
        # 写入state_mean
        f.write('float state_mean[] = {\n')
        if len(state_mean.shape) == 2:
            for col in range(state_mean.shape[1]):
                row_str = ', '.join(f'{state_mean[row,col]:.6f}' for row in range(state_mean.shape[0]))
                f.write(f'    {row_str}')
                f.write(',\n' if col < state_mean.shape[1]-1 else '\n')
        else:
            f.write(f'    // {state_mean.shape[0]}\n')  
            f.write('    ' + ', '.join(f'{x:.6f}' for x in state_mean.flatten()) + '\n')
        f.write('};\n\n')
        
        # 写入state_std
        f.write('float state_std[] = {\n')
        if len(state_std.shape) == 2:
            for col in range(state_std.shape[1]):
                row_str = ', '.join(f'{state_std[row,col]:.6f}' for row in range(state_std.shape[0]))
                f.write(f'    {row_str}')
                f.write(',\n' if col < state_std.shape[1]-1 else '\n')
        else:
            f.write(f'    // {state_std.shape[0]}\n')  
            f.write('    ' + ', '.join(f'{x:.6f}' for x in state_std.flatten()) + '\n')
        f.write('};\n\n')
        
        # 写入weights
        f.write('float weights[] = {\n')
        for key, value in sorted(policy_params['params'].items()):
            print(key, value.keys(), value['kernel'].shape)
            param = np.array(value['kernel'], dtype=np.float32)
            if len(param.shape) == 2:
                print("param[:10, 0]:", param[:10, 0])
                print("param[:10, 1]:", param[:10, 1])
                f.write(f'    // {param.shape[0]}x{param.shape[1]}\n')  
                for col in range(param.shape[1]):
                    row_str = ', '.join(f'{param[row,col]:.6f}' for row in range(param.shape[0]))
                    f.write(f'    {row_str}, \n')
                f.write('\n\n')  # 层间空行
            else:
                f.write('    ' + ', '.join(f'{x:.6f}' for x in param.flatten()) + '\n\n')
        f.write('};\n\n')
        
        # 写入biases
        f.write('float biases[] = {\n')
        for key, value in sorted(policy_params['params'].items()):
            print(key, value.keys(), value['bias'].shape)
            param = np.array(value['bias'], dtype=np.float32)
            if len(param.shape) == 2:
                for col in range(param.shape[1]):
                    row_str = ', '.join(f'{param[row,col]:.6f}' for row in range(param.shape[0]))
                    f.write(f'    {row_str}, \n')
                f.write('\n\n')  # 层间空行
            else:
                f.write(f'    // {param.shape[0]}\n')  
                f.write('    ' + ', '.join(f'{x:.6f}' for x in param.flatten()) + ',\n\n')
        f.write('};\n')
    
    print('参数已按列格式保存到params.cpp')


